prompt:
Create exactly 5 independent, realistic RTL bug mutants of the supplied reference.
Each mutant must be based on the original RTL and represent one plausible implementation mistake,
ideally a distinct behavior observable on an output after a legal input sequence. Use a compact and local
change, without changing the interface, synthesizability, testbench, or introducing any new files or system tasks.
Favor bugs in data selection, boundary conditions, bit widths, priority and interactions between datapath and control, where applicable. Avoid five interchangeable constant changes.
Output valid JSON only, with a top-level "mutants" array. Each entry has "bug" (a short plain description)
and "edits" (a list of objects with two JSON strings "old" and "new"). Each "old" must occur exactly once
verbatim in the supplied source, including whitespace. Prefer a single targeted replacement per mutant;
use multiple disjoint edits only when necessary to model one bug. No markdown.
Reference RTL for top_manchester:
module top_manchester #(
    parameter N = 8  // Default width of input and output data
) (
    input  logic           clk_in,          // Clock input
    input  logic           rst_in,          // Active high reset input

    // Encoder Signals
    input  logic           enc_valid_in,    // Input valid signal
    input  logic [N-1:0]   enc_data_in,     // N-bit input data
    output logic           enc_valid_out,   // Output valid signal
    output logic [2*N-1:0] enc_data_out,    // 2*N-bit encoder output data

    // Decoder Signals
    input  logic           dec_valid_in,    // Input valid signal
    input  logic [2*N-1:0] dec_data_in,     // 2*N-bit input data
    output logic           dec_valid_out,   // Output valid signal
    output logic [N-1:0]   dec_data_out     // N-bit output decoded data
);

    always_ff @(posedge clk_in) begin
        if (rst_in) begin
            enc_data_out  <= '0; 
            enc_valid_out <= 1'b0; 
        end else if (enc_valid_in) begin
            for (int i = 0; i < N; i++) begin
                if (enc_data_in[i] == 1'b1) begin
                    enc_data_out[2*i]   <= 1'b1;
                    enc_data_out[2*i+1] <= 1'b0;
                end else begin
                    enc_data_out[2*i]   <= 1'b0;
                    enc_data_out[2*i+1] <= 1'b1;
                end
            end
            enc_valid_out <= 1'b1;
        end else begin
            enc_data_out  <= 'd0;
            enc_valid_out <= 1'b0;
        end
    end

    always_ff @(posedge clk_in) begin
        if (rst_in) begin
            dec_data_out  <= '0; 
            dec_valid_out <= 1'b0;
        end else if (dec_valid_in) begin
            for (int i = 0; i < N; i++) begin
                if (dec_data_in[2*i] == 1'b1 && dec_data_in[2*i+1] == 1'b0) begin
                    dec_data_out[i] <= 1'b1;
                end else if (dec_data_in[2*i] == 1'b0 && dec_data_in[2*i+1] == 1'b1) begin
                    dec_data_out[i] <= 1'b0;
                end else begin
                    dec_data_out[i] <= 1'b0;
                end
            end
            dec_valid_out <= 1'b1;
        end else begin
            dec_data_out  <= '0;
            dec_valid_out <= 1'b0;
        end
    end

endmodule

